def compute(vars):
    debt_obligations = vars["v1"]
    purchase_obligations = vars["v2"]
    value = debt_obligations - purchase_obligations
    return {
        "value": value,
        "trace": {
            "debt_obligations": debt_obligations,
            "purchase_obligations": purchase_obligations,
            "difference": value,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
